from pathlib import Path
import json,hashlib,fitz,argparse
parser=argparse.ArgumentParser();parser.add_argument('--downloads',type=Path,required=True);args=parser.parse_args()
R=Path(__file__).resolve().parents[1];S=args.downloads;docs={d['id']:d for d in json.loads((R/'catalogue.json').read_text())['documents']}
groups=[]
def add(id,doc,page,title,box,items,scope=''):
 d=docs[doc];source=S/d['download_filename'];pdf=fitz.open(source);p=pdf[page-1];rect=fitz.Rect(p.rect.width*box[0],p.rect.height*box[1],p.rect.width*box[2],p.rect.height*box[3]);out=R/'assets/figures'/f'{id}.png';out.parent.mkdir(parents=True,exist_ok=True);pix=p.get_pixmap(dpi=200,clip=rect,alpha=False);pix.save(out)
 groups.append({'id':id,'document':doc,'source_page':page,'source_sha256':d['original_sha256'],'title':title,'scope':scope or d['model_scope'],'file':out.relative_to(R).as_posix(),'crop_points':list(rect),'image_pixels':[pix.width,pix.height],'sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'processing':'Faithful 200 dpi colour crop; original diagrams, callouts and labels retained. No labels invented or replaced. Complete source-page link accompanies the figure.','components':[{'locator':str(a),'name':b,'explanation':c} for a,b,c in items]});pdf.close()
