add('feeder-system','CAT-07',11,'Inside the paver: the feeder system',(.05,.07,.96,.61),[('label','Feeder bed plate','Wear surface beneath material moving through the feeder system.'),('label','Feeder chain guard','Protective wear plate associated with the feeder-chain path.'),('label','Foot shaft','Shaft at the foot end of the feeder assembly.'),('label','Feeder chain','Linked assembly that carries material through the feeder path.'),('label','Head shaft','Shaft at the head end of the feeder assembly.')])
add('auger-assembly','CAT-07',15,'Auger parts: identify the assembly',(.04,.07,.97,.58),[('label','Auger segments','Spiral sections that move mixture across the width.'),('label','Deflector','Guides material near the auger assembly.'),('label','Auger bearings','Support the rotating auger shaft.'),('label','Auger shaft','Shaft on which the auger segments are mounted.')])
add('paver-undercarriage','CAT-07',19,'Paver contact with the ground',(.05,.08,.96,.9),[('photo','Smooth belt','Ground-contact belt used on the illustrated track arrangement.'),('photo','Track pads','Wear/contact pads on the illustrated track arrangement.'),('photo','Track plow','Scraper ahead of the track contact area.')])
add('screed-plates','CAT-07',22,'Screed plates and heating components',(.04,.07,.97,.43),[('label','Deflectors','Guide material at the screed assembly.'),('label','Screed plates','Lower wear surfaces that contact the placed mixture.'),('label','Nose bars','Wear components at the leading part of the screed plate arrangement.'),('label','Heating elements','Heat the applicable electrically heated screed components.')])
add('tamper-screed','CAT-07',28,'Look inside a tamper-bar screed',(.04,.09,.97,.59),[('label','Deflector','Material-guiding component.'),('label','Tamper blade','Working element in the tamping assembly.'),('label','Tamper bar','Bar assembly that provides tamping action.'),('label','Wear plate','Replaceable wear surface in the illustrated assembly.'),('label','Screed plate','Surface that shapes the mat.'),('label','Heating element','Heater for the applicable component.'),('label','Tamper motor','Drive component for the tamping system.')])
add('grade-sensors','CAT-07',34,'Identify grade and slope sensors',(.04,.08,.97,.92),[('photo','Sonic grade sensor','Non-contact grade-reference sensor.'),('photo','Mechanical grade sensor','Contacting sensor with a wand/riding shoe.'),('photo','Extendable sonic grade sensor','Sonic sensor with an extendable mounting arrangement.'),('photo','Extendable mechanical grade sensor','Mechanical sensor with an extendable mounting arrangement.'),('photo','Slope sensor','Sensor associated with the transverse beam for slope information.')])
add('feed-sensors','CAT-07',43,'Feed sensing and hopper information',(.04,.07,.97,.93),[('photo','Sonic material feed sensors','Sense material around conveyor discharge or auger ends in the applicable arrangement.'),('photo','Paddle material feed sensors','Contacting material sensors in the auger chamber.'),('photo','Hopper material level and temperature sensor','Reports hopper material information on applicable configurations.')])
add('milling-rotor','CAT-08',8,'Cutting system: rotor details',(.07,.52,.9,.92),[('label','Kicker paddles','Move cut material through the rotor system.'),('label','Fastener-free toolholder','Holds the applicable cutting tool in the illustrated System K design.'),('detail','Tooth / cutting bit','Cutting tool that contacts the material being removed.')],'Cat System K rotor example. Other rotor systems and retaining arrangements differ; no change-out procedure is taught here.')
add('cutting-chamber','CAT-08',18,'Four wear components around the cutting chamber',(.04,.07,.97,.59),[('1','Anti-slab wear skis','Wear surfaces associated with the anti-slab arrangement.'),('2','Moldboard cutting edges','Wear edges at the rear of the cutting chamber.'),('3','Sidegate wear skis','Wear surfaces at the chamber sides.'),('4','Inboard grade control wear ski','Wear ski used with the inboard grade-control arrangement.')])
add('rotor-drive','CAT-08',22,'Rotor drive components',(.04,.08,.97,.59),[('1','Rotor drive belt','Transfers drive through the rotor-drive arrangement.'),('2','Tensioner idler','Idler on the belt tensioner arm.'),('3','Sheave','Grooved wheel that interfaces with the rotor drive belt.')])
