add('milling-undercarriage','CAT-08',32,'Every numbered component in this track diagram',(.04,.08,.97,.55),[('1','Track pads','Ground-contact pads on this undercarriage.'),('2','Sprockets','Transfer driving loads into the tracks.'),('3','Rollers','Support/guide the track arrangement.'),('4','Idlers','Guide the track at the idler end.'),('5','Track shoes','Interface with the track pads in this arrangement.'),('6','Track chain','Linked track assembly that travels around the undercarriage.')])
