add('steering-frame-lock','CAT-10',38,'Articulation and the steering frame lock',(.02,.35,.50,.58),[('1','Pin','Retaining pin identified in the source illustration.'),('2','Eye hole','Alignment opening identified in the source illustration.'),('assembly','Steering frame lock','Mechanical assembly used to restrict articulation under the manual’s specified conditions.')],docs['CAT-10']['model_scope']+' Read the complete source page for locking/unlocking instructions; this task is identification only.')
