(R/'atlas.json').write_text(json.dumps({'figures':groups,'component_rows':sum(len(f['components']) for f in groups),'scope':'Every callout is transcribed for the selected numbered conveyor, undercarriage and roller-control diagrams. Other figures have selected names. The full searchable publications supply additional component tables. This is not an exhaustive serial-specific parts catalogue.'},ensure_ascii=False,indent=2)+'\n')
